<?php
namespace App\Controllers;use App\Services\CartService;use App\Services\StorefrontService;
class CartController extends BaseController
{public function index(){$s=new CartService();return view('frontend/cart/index',['title'=>'আপনার কার্ট','cart'=>$s->resolve(),'settings'=>(new StorefrontService())->settings()]);}public function add(){try{$s=new CartService();$type=(string)$this->request->getPost('item_type');$type==='package'?$s->addPackage((int)$this->request->getPost('package_id'),(int)$this->request->getPost('quantity')):$s->addProduct((int)$this->request->getPost('product_id'),(int)$this->request->getPost('variant_id')?:null,(int)$this->request->getPost('quantity'));return redirect()->back()->with('success','কার্টে যোগ হয়েছে।');}catch(\Throwable $e){return redirect()->back()->with('danger',$e->getMessage());}}public function update(){try{(new CartService())->replace((array)$this->request->getPost('quantities'));return redirect()->back()->with('success','কার্ট আপডেট হয়েছে।');}catch(\Throwable $e){return redirect()->back()->with('danger',$e->getMessage());}}public function remove(){(new CartService())->remove((string)$this->request->getPost('key'));return redirect()->back()->with('success','পণ্যটি সরানো হয়েছে।');}public function clear(){(new CartService())->clear();return redirect()->back()->with('success','কার্ট খালি করা হয়েছে।');}public function buyNow(){try{$type=(string)$this->request->getPost('item_type');$item=['item_type'=>$type,'product_id'=>$type==='product'?(int)$this->request->getPost('product_id'):null,'variant_id'=>(int)$this->request->getPost('variant_id')?:null,'package_id'=>$type==='package'?(int)$this->request->getPost('package_id'):null,'quantity'=>(int)$this->request->getPost('quantity')];$s=new CartService();$resolved=$s->one($item);if($resolved['errors']||!$resolved['items'])throw new \RuntimeException($resolved['errors'][0]??'পণ্যটি পাওয়া যায়নি।');session()->set(['checkout_mode'=>'buy_now','checkout_item'=>$item]);return redirect()->to(url_to('checkout.index'));}catch(\Throwable $e){return redirect()->back()->with('danger',$e->getMessage());}}}
